import{_ as o,o as p,c as r,a2 as e}from"./chunks/framework.BXzK3EA4.js";const d=JSON.parse('{"title":"linux系统如何传输数据","description":"","frontmatter":{"title":"linux系统如何传输数据"},"headers":[],"relativePath":"ops-knowledge-base/operating-system/linux/how-to-transfer-data.md","filePath":"ops-knowledge-base/operating-system/linux/how-to-transfer-data.md","lastUpdated":1788259091000}'),s={name:"ops-knowledge-base/operating-system/linux/how-to-transfer-data.md"};function n(a,t,l,i,f,g){return p(),r("div",null,[...t[0]||(t[0]=[e('<p><strong>scp****命令</strong>用于在Linux下进行远程拷贝文件的命令。scp命令可以在多台Linux系统之间复制文件或目录 ，有些类似于cp命令的功能，但复制的范围却不是本地，而是网络上另一台主机。</p><p>语法格式：scp 参数 文件或目录名 [远程服务器信息]</p><p>常用参数</p><p>-1：使用ssh协议版本1；</p><p>-2：使用ssh协议版本2；</p><p>-4：使用ipv4；</p><p>-6：使用ipv6；</p><p>-B：以批处理模式运行；</p><p>-C：使用压缩；</p><p>-F：指定ssh配置文件；</p><p>-i：identity_file 从指定文件中读取传输时使用的密钥文件（例如亚马逊云pem），此参数直接传递给ssh；</p><p>-l：指定宽带限制；</p><p>-o：指定使用的ssh选项；</p><p>-P：指定远程主机的端口号；</p><p>-p：保留文件的最后修改时间，最后访问时间和权限模式；</p><p>-q：不显示复制进度；</p><p>-r：以递归方式复制。</p><p><strong>参数</strong></p><ul><li>源文件：指定要复制的源文件。</li><li>目标文件：目标文件。格式为user@host：filename（文件名为目标文件的名称）</li></ul><p><strong>实例</strong></p><p>从远程复制到本地的scp命令与上面的命令雷同，只要将从本地复制到远程的命令后面2个参数互换顺序就行了。</p><p><strong>1.从远程机器复制文件到本地目录</strong></p><p>scp <a href="mailto:root@10.10.10.10" target="_blank" rel="noreferrer">root@10.10.10.10</a>:/opt/soft/nginx-0.5.38.tar.gz /opt/soft/</p><p>从10.10.10.10机器上的/opt/soft/的目录中下载nginx-0.5.38.tar.gz 文件到本地/opt/soft/目录中。</p><p><strong>2.从亚马逊云复制OpenVPN到本地目录</strong></p><p>scp -i amazon.pem <a href="mailto:ubuntu@10.10.10.10" target="_blank" rel="noreferrer">ubuntu@10.10.10.10</a>:/usr/local/openvpn_as/etc/exe/openvpn-connect-2.1.3.110.dmg openvpn-connect-2.1.3.110.dmg</p><p>从10.10.10.10机器上下载openvpn安装文件到本地当前目录来。</p><p><strong>3.从远程机器复制到本地</strong></p><p>scp -r <a href="mailto:root@10.10.10.10" target="_blank" rel="noreferrer">root@10.10.10.10</a>:/opt/soft/mongodb /opt/soft/</p><p>从10.10.10.10机器上的/opt/soft/中下载mongodb目录到本地的/opt/soft/目录来。</p><p><strong>4.上传本地文件到远程机器指定目录</strong></p><p>scp /opt/soft/nginx-0.5.38.tar.gz <a href="mailto:root@10.10.10.10" target="_blank" rel="noreferrer">root@10.10.10.10</a>:/opt/soft/scptest</p><h2 id="指定端口-2222" tabindex="-1">指定端口 2222 <a class="header-anchor" href="#指定端口-2222" aria-label="Permalink to &quot;指定端口 2222&quot;">​</a></h2><p>scp -rp -P 2222 /opt/soft/nginx-0.5.38.tar.gz <a href="mailto:root@10.10.10.10" target="_blank" rel="noreferrer">root@10.10.10.10</a>:/opt/soft/scptest</p><p>复制本地/opt/soft/目录下的文件nginx-0.5.38.tar.gz到远程机器10.10.10.10的opt/soft/scptest目录。</p><p><strong>5.上传本地目录到远程机器指定目录</strong></p><p>scp -r /opt/soft/mongodb <a href="mailto:root@10.10.10.10" target="_blank" rel="noreferrer">root@10.10.10.10</a>:/opt/soft/scptest</p><p>上传本地目录/opt/soft/mongodb到远程机器10.10.10.10上/opt/soft/scptest的目录中去。</p>',38)])])}const m=o(s,[["render",n]]);export{d as __pageData,m as default};
